import type { ItemDef } from '../types';

export type CraftStation = 'kitchen' | 'bench' | 'infirmary' | 'forge' | 'alchemy';
export interface CraftRecipe {
  id: string;
  result: string;
  /** Unidades que salen por cada vez. */
  qty: number;
  station: CraftStation;
  /** Nivel del espacio que la enseña (1–3). */
  level: 1 | 2 | 3;
  ingredients: { itemId: string; qty: number }[];
  /** Plano que hay que aprender (id del objeto plano). Sin valor: viene con el nivel. */
  blueprint?: string;
  /** Material fino opcional (+25 % de acabado fino). Solo en lo que puede subir de rareza. */
  fine?: string;
}

